// Location is a place on earth: where to calculate *zmanim* for. Heights are in meters above sea level;
// leave them 0 for sea level.
//
// The time zone is not part of the location. You pass a `LocalDay` to `Zmanim` and
// `MyZmanim` when you create them.
type Location struct {
	// Latitude in degrees, north positive.
	Latitude float64
	// Longitude in degrees, east positive.
	Longitude float64
	// Elevation is the observer's height. Elevation makes sunrise earlier and sunset later.
	Elevation float64
	// EasternHorizonElevation is the height of the eastern horizon, over which the sun rises.
	EasternHorizonElevation float64
	// WesternHorizonElevation is the height of the western horizon, behind which the sun sets.
	WesternHorizonElevation float64
}

func wvWriteLocation(w *wvWriter, v Location) {
	w.writeF64(v.Latitude)
	w.writeF64(v.Longitude)
	w.writeF64(v.Elevation)
	w.writeF64(v.EasternHorizonElevation)
	w.writeF64(v.WesternHorizonElevation)
}

func wvReadLocation(r *wvReader) Location {
	var v Location
	v.Latitude = r.readF64()
	v.Longitude = r.readF64()
	v.Elevation = r.readF64()
	v.EasternHorizonElevation = r.readF64()
	v.WesternHorizonElevation = r.readF64()
	return v
}

// LocalDay is the date in the caller's time zone: when local midnight starts it, when local midnight
// starts the next date, and the offset from UTC at each. Compute it with your platform's
// time zone support, for example `date.atStartOfDay(zone)` and
// `date.plusDays(1).atStartOfDay(zone)` in Java.
//
// When the clocks skip midnight, the day starts at the first instant the clocks show that
// day, such as 01:00. A day the clocks skip entirely starts and ends at the same instant.
//
// The local day is optional. With one every time works. You can also leave it out. These do
// not work without one:
//
// - The four Kiddush Levana times return `ZmanimError::TimeZoneRequired`.
// - `Zmanim` and `MyZmanim` cannot be created for a location more than 150 degrees from
//   Greenwich. Creating them returns `ZmanimError::TimeZoneRequired`.
type LocalDay struct {
	// StartMs is when local midnight starts the date, in Unix milliseconds.
	StartMs int64
	// StartOffsetSeconds is the offset from UTC at `start_ms`, in seconds east.
	StartOffsetSeconds int32
	// EndMs is when local midnight starts the next date, in Unix milliseconds.
	EndMs int64
	// EndOffsetSeconds is the offset from UTC at `end_ms`, in seconds east.
	EndOffsetSeconds int32
}

func wvWriteLocalDay(w *wvWriter, v LocalDay) {
	w.writeI64(v.StartMs)
	w.writeI32(v.StartOffsetSeconds)
	w.writeI64(v.EndMs)
	w.writeI32(v.EndOffsetSeconds)
}

func wvReadLocalDay(r *wvReader) LocalDay {
	var v LocalDay
	v.StartMs = r.readI64()
	v.StartOffsetSeconds = r.readI32()
	v.EndMs = r.readI64()
	v.EndOffsetSeconds = r.readI32()
	return v
}

// Config is how `Zmanim` calculates. `default_config` matches KosherJava's defaults.
type Config struct {
	// CandleLightingMinutes is how long before sea-level sunset candle lighting is, in minutes, from 0 to 1440.
	// Default 18.
	CandleLightingMinutes int32
	// UseAstronomicalChatzosForOtherZmanim reports whether proportional zmanim divide the day at astronomical *chatzos*. Default false.
	UseAstronomicalChatzosForOtherZmanim bool
	// UseElevation reports whether elevation adjusts every zman built on sunrise and sunset, not only sunrise
	// and sunset themselves. Default false.
	UseElevation bool
	// AteretTorahSunsetMinutes is how long after sunset Tzais Ateret Torah is, in minutes, at most 1440 either way.
	// Default 40.
	AteretTorahSunsetMinutes int32
	// UseAstronomicalChatzos reports whether *chatzos* is the sun's transit rather than the midpoint of sunrise and
	// sunset. Default true.
	UseAstronomicalChatzos bool
	// Calculator is the solar position algorithm. Default NOAA.
	Calculator Calculator
	// ApplyDeltaT: For Meeus and SPA: whether to apply the delta-T (TT - UT) correction. Default true.
	ApplyDeltaT bool
}

func wvWriteConfig(w *wvWriter, v Config) {
	w.writeI32(v.CandleLightingMinutes)
	w.writeBool(v.UseAstronomicalChatzosForOtherZmanim)
	w.writeBool(v.UseElevation)
	w.writeI32(v.AteretTorahSunsetMinutes)
	w.writeBool(v.UseAstronomicalChatzos)
	wvWriteCalculator(w, v.Calculator)
	w.writeBool(v.ApplyDeltaT)
}

func wvReadConfig(r *wvReader) Config {
	var v Config
	v.CandleLightingMinutes = r.readI32()
	v.UseAstronomicalChatzosForOtherZmanim = r.readBool()
	v.UseElevation = r.readBool()
	v.AteretTorahSunsetMinutes = r.readI32()
	v.UseAstronomicalChatzos = r.readBool()
	v.Calculator = wvReadCalculator(r)
	v.ApplyDeltaT = r.readBool()
	return v
}

// ZmanTime: One zman's time, or why it has none.
type ZmanTime struct {
	// Zman is the zman.
	Zman Zman
	// Time is the time in Unix milliseconds, when it could be calculated.
	Time *int64
	// Failure is why it could not, when it could not.
	Failure *ZmanFailure
}

func wvWriteZmanTime(w *wvWriter, v ZmanTime) {
	wvWriteZman(w, v.Zman)
	wvWriteOptI64(w, v.Time)
	wvWriteOptZmanFailure(w, v.Failure)
}

func wvReadZmanTime(r *wvReader) ZmanTime {
	var v ZmanTime
	v.Zman = wvReadZman(r)
	v.Time = wvReadOptI64(r)
	v.Failure = wvReadOptZmanFailure(r)
	return v
}

// Zmanim is the *zmanim* for one place on one day.
//
// Each wrapper holds one strong reference; Close releases it, and a finalizer
// releases it if the wrapper is garbage collected first.
type Zmanim struct {
	ref wvRef
}

func wvDestroyZmanim(ptr unsafe.Pointer) {
	C.kosherz_times_Zmanim_destroy((*C.kosherz_times_Zmanim)(ptr))
}

// wvAdoptZmanim wraps one owned strong reference. A null pointer adopts to nil.
func wvAdoptZmanim(ptr *C.kosherz_times_Zmanim) *Zmanim {
	if ptr == nil {
		return nil
	}
	s := &Zmanim{}
	s.ref.init(unsafe.Pointer(ptr), wvDestroyZmanim)
	runtime.SetFinalizer(s, (*Zmanim).Close)
	return s
}

// native borrows the wrapper's pointer for one call; pair it with a
// deferred s.ref.release().
func (s *Zmanim) native() *C.kosherz_times_Zmanim {
	if s == nil {
		panic("kosherz: nil *Zmanim")
	}
	return (*C.kosherz_times_Zmanim)(s.ref.acquire("Zmanim"))
}

// share returns a new strong reference to the wrapper's object for the
// native library to adopt (the wrapper keeps its own), or null for nil.
func (s *Zmanim) share() *C.kosherz_times_Zmanim {
	if s == nil {
		return nil
	}
	ptr := s.native()
	defer s.ref.release()
	return C.kosherz_times_Zmanim_clone(ptr)
}

// Close releases the wrapper's strong reference and always returns nil.
// It's idempotent and safe to call from any goroutine, even while a call
// on the wrapper is in flight: the reference is then released when that
// call returns. The object itself is dropped once its last reference, from
// any wrapper, record, or the native library, is gone.
func (s *Zmanim) Close() error {
	runtime.SetFinalizer(s, nil)
	s.ref.close()
	return nil
}

// NewZmanim returns the *zmanim* at `location` on `date`, whose local day is `local_day`, calculated with
// `config`.
//
// The local day is optional. With one every time works. Without one the four Kiddush
// Levana times return `ZmanimError::TimeZoneRequired`. A location more than 150 degrees
// from Greenwich needs one. Without one this returns `ZmanimError::TimeZoneRequired`.
//
// # Errors
//
// - `ZmanimError::InvalidGregorianDate` when the date does not exist.
// - `ZmanimError::InvalidMinutes` when the candle-lighting offset is negative, or it or the
//   Ateret Torah offset is more than a day.
// - `ZmanimError::InvalidLocalDay` when `local_day` is impossible.
// - The errors of `validate_location`. This includes `ZmanimError::TimeZoneRequired` when
//   there is no local day and the location is more than 150 degrees from Greenwich.
func NewZmanim(location Location, date GregorianDate, config Config, localDay *LocalDay) (*Zmanim, error) {
	cLocationPtr, cLocationLen := wvBytes(wvEncode(location, wvWriteLocation))
	cDatePtr, cDateLen := wvBytes(wvEncode(date, wvWriteGregorianDate))
	cConfigPtr, cConfigLen := wvBytes(wvEncode(config, wvWriteConfig))
	cLocalDayPtr, cLocalDayLen := wvBytes(wvEncode(localDay, wvWriteOptLocalDay))
	var cErr C.kosherz_error
	cRet := C.kosherz_times_Zmanim_new(cLocationPtr, cLocationLen, cDatePtr, cDateLen, cConfigPtr, cConfigLen, cLocalDayPtr, cLocalDayLen, &cErr)
	if cErr.code != 0 {
		return nil, wvZmanimError(wvTakeError(&cErr))
	}
	return wvAdoptZmanim(cRet), nil
}

// Get returns the time of `zman`, in Unix milliseconds.
//
// # Errors
//
// `ZmanimError::AllDay` or `ZmanimError::AllNight` where the sun never reaches
// the angle the time needs; `ZmanimError::NotApplicable` for a time that only exists
// on some days; `ZmanimError::TimeZoneRequired` for the Kiddush Levana times without
// a local day.
func (s *Zmanim) Get(zman Zman) (int64, error) {
	cSelf := s.native()
	defer s.ref.release()
	var cErr C.kosherz_error
	cRet := C.kosherz_times_Zmanim_get(cSelf, C.kosherz_times_Zman(zman), &cErr)
	if cErr.code != 0 {
		return 0, wvZmanimError(wvTakeError(&cErr))
	}
	return int64(cRet), nil
}

