// MyZmanTime: One MyZmanim time, or why it has none.
type MyZmanTime struct {
	// Zman is the row.
	Zman MyZman
	// Time is the time in Unix milliseconds, when it could be calculated.
	Time *int64
	// Failure is why it could not, when it could not.
	Failure *ZmanFailure
}

func wvWriteMyZmanTime(w *wvWriter, v MyZmanTime) {
	wvWriteMyZman(w, v.Zman)
	wvWriteOptI64(w, v.Time)
	wvWriteOptZmanFailure(w, v.Failure)
}

func wvReadMyZmanTime(r *wvReader) MyZmanTime {
	var v MyZmanTime
	v.Zman = wvReadMyZman(r)
	v.Time = wvReadOptI64(r)
	v.Failure = wvReadOptZmanFailure(r)
	return v
}

// MyZmanim: MyZmanim's *zmanim* for one place on one day. The location's elevation and horizons
// matter: MyZmanim gives both "level" and "elevated" sunrise and sunset.
//
// Each wrapper holds one strong reference; Close releases it, and a finalizer
// releases it if the wrapper is garbage collected first.
type MyZmanim struct {
	ref wvRef
}

func wvDestroyMyZmanim(ptr unsafe.Pointer) {
	C.kosherz_times_myzmanim_MyZmanim_destroy((*C.kosherz_times_myzmanim_MyZmanim)(ptr))
}

// wvAdoptMyZmanim wraps one owned strong reference. A null pointer adopts to nil.
func wvAdoptMyZmanim(ptr *C.kosherz_times_myzmanim_MyZmanim) *MyZmanim {
	if ptr == nil {
		return nil
	}
	s := &MyZmanim{}
	s.ref.init(unsafe.Pointer(ptr), wvDestroyMyZmanim)
	runtime.SetFinalizer(s, (*MyZmanim).Close)
	return s
}

// native borrows the wrapper's pointer for one call; pair it with a
// deferred s.ref.release().
func (s *MyZmanim) native() *C.kosherz_times_myzmanim_MyZmanim {
	if s == nil {
		panic("kosherz: nil *MyZmanim")
	}
	return (*C.kosherz_times_myzmanim_MyZmanim)(s.ref.acquire("MyZmanim"))
}

// share returns a new strong reference to the wrapper's object for the
// native library to adopt (the wrapper keeps its own), or null for nil.
func (s *MyZmanim) share() *C.kosherz_times_myzmanim_MyZmanim {
	if s == nil {
		return nil
	}
	ptr := s.native()
	defer s.ref.release()
	return C.kosherz_times_myzmanim_MyZmanim_clone(ptr)
}

// Close releases the wrapper's strong reference and always returns nil.
// It's idempotent and safe to call from any goroutine, even while a call
// on the wrapper is in flight: the reference is then released when that
// call returns. The object itself is dropped once its last reference, from
// any wrapper, record, or the native library, is gone.
func (s *MyZmanim) Close() error {
	runtime.SetFinalizer(s, nil)
	s.ref.close()
	return nil
}

// NewMyZmanim returns the *zmanim* at `location` on `date`, whose local day is `local_day`. Candles are lit
// `candle_lighting_minutes` before sunset. The website uses 18 minutes by default.
//
// The local day is optional. With one every time works. A location more than 150
// degrees from Greenwich needs one. Without one this returns
// `ZmanimError::TimeZoneRequired`.
//
// # Errors
//
// - `ZmanimError::InvalidGregorianDate` when the date does not exist.
// - `ZmanimError::InvalidMinutes` when `candle_lighting_minutes` is not a number from
//   0 to 1440.
// - `ZmanimError::InvalidLocalDay` when `local_day` is impossible.
// - The errors of `validate_location`. This includes `ZmanimError::TimeZoneRequired`
//   when there is no local day and the location is more than 150 degrees from
//   Greenwich.
func NewMyZmanim(location Location, date GregorianDate, candleLightingMinutes float64, localDay *LocalDay) (*MyZmanim, error) {
	cLocationPtr, cLocationLen := wvBytes(wvEncode(location, wvWriteLocation))
	cDatePtr, cDateLen := wvBytes(wvEncode(date, wvWriteGregorianDate))
	cLocalDayPtr, cLocalDayLen := wvBytes(wvEncode(localDay, wvWriteOptLocalDay))
	var cErr C.kosherz_error
	cRet := C.kosherz_times_myzmanim_MyZmanim_new(cLocationPtr, cLocationLen, cDatePtr, cDateLen, C.double(candleLightingMinutes), cLocalDayPtr, cLocalDayLen, &cErr)
	if cErr.code != 0 {
		return nil, wvZmanimError(wvTakeError(&cErr))
	}
	return wvAdoptMyZmanim(cRet), nil
}

// Get returns the time of `zman`, in Unix milliseconds.
//
// # Errors
//
// `ZmanimError::AllDay` or `ZmanimError::AllNight` where the website shows no
// time.
func (s *MyZmanim) Get(zman MyZman) (int64, error) {
	cSelf := s.native()
	defer s.ref.release()
	var cErr C.kosherz_error
	cRet := C.kosherz_times_myzmanim_MyZmanim_get(cSelf, C.kosherz_times_myzmanim_MyZman(zman), &cErr)
	if cErr.code != 0 {
		return 0, wvZmanimError(wvTakeError(&cErr))
	}
	return int64(cRet), nil
}

